-- Схеми автоматизованого контролю якості даних, карантину та валідованого шару (quality, quarantine, validated).
CREATE SCHEMA IF NOT EXISTS quality;
CREATE SCHEMA IF NOT EXISTS quarantine;
CREATE SCHEMA IF NOT EXISTS validated;

CREATE TABLE IF NOT EXISTS quality.runs (
 run_id uuid PRIMARY KEY, student_id text NOT NULL, scope text NOT NULL,
 reference_time timestamptz NOT NULL, contract_version text NOT NULL,
 status text NOT NULL CHECK(status IN ('RUNNING','PASS','WARN','BLOCKED','FAILED')),
 started_at timestamptz NOT NULL DEFAULT clock_timestamp(), finished_at timestamptz,
 source_manifest jsonb NOT NULL, error_code text
);
CREATE TABLE IF NOT EXISTS quality.row_decisions (
 run_id uuid NOT NULL REFERENCES quality.runs, source_name text NOT NULL,
 source_row_no integer NOT NULL, business_key text,
 decision text NOT NULL CHECK(decision IN ('accepted','rejected','duplicate')),
 reason_codes jsonb NOT NULL DEFAULT '[]',
 PRIMARY KEY(run_id,source_name,source_row_no)
);
CREATE TABLE IF NOT EXISTS quality.rule_results (
 run_id uuid NOT NULL REFERENCES quality.runs, rule_id text NOT NULL,
 severity text NOT NULL CHECK(severity IN ('REJECT','WARN','BLOCK','DUPLICATE')),
 failed_count bigint NOT NULL CHECK(failed_count>=0), details jsonb,
 PRIMARY KEY(run_id,rule_id)
);
CREATE TABLE IF NOT EXISTS quarantine.records (
 run_id uuid NOT NULL, source_name text NOT NULL, source_row_no integer NOT NULL,
 payload jsonb NOT NULL, reason_codes jsonb NOT NULL,
 PRIMARY KEY(run_id,source_name,source_row_no),
 FOREIGN KEY(run_id,source_name,source_row_no)
  REFERENCES quality.row_decisions(run_id,source_name,source_row_no)
);
CREATE TABLE IF NOT EXISTS validated.orders (
 order_id text PRIMARY KEY,customer_id text NOT NULL,merchant_id text NOT NULL,
 created_at timestamptz NOT NULL,order_status text NOT NULL,currency text NOT NULL,
 subtotal_amount numeric(12,2) NOT NULL,delivery_fee numeric(12,2) NOT NULL,
 discount_amount numeric(12,2) NOT NULL,total_amount numeric(12,2) NOT NULL,
 quality_run_id uuid NOT NULL REFERENCES quality.runs
);
CREATE TABLE IF NOT EXISTS validated.order_items (
 order_item_id text PRIMARY KEY,order_id text NOT NULL REFERENCES validated.orders,
 product_id text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),
 unit_price numeric(12,2) NOT NULL,line_discount numeric(12,2) NOT NULL,
 line_total numeric(12,2) NOT NULL,currency text NOT NULL,
 quality_run_id uuid NOT NULL REFERENCES quality.runs
);
CREATE TABLE IF NOT EXISTS validated.delivery_events (
 event_id text PRIMARY KEY,delivery_id text NOT NULL,
 order_id text NOT NULL REFERENCES validated.orders,event_type text NOT NULL,
 occurred_at timestamptz NOT NULL,available_at timestamptz NOT NULL,
 courier_id text,service_zone_id text,payload_version integer NOT NULL,
 payload jsonb NOT NULL,quality_run_id uuid NOT NULL REFERENCES quality.runs
);

-- Джерельний шар інгестії для експорту додаткових замовлень та подій доставки (S03):
CREATE SCHEMA IF NOT EXISTS ingestion_stg;
CREATE TABLE IF NOT EXISTS ingestion_stg.orders (
    student_id text NOT NULL,
    order_id text NOT NULL,
    payload jsonb NOT NULL,
    PRIMARY KEY (student_id, order_id)
);
CREATE TABLE IF NOT EXISTS ingestion_stg.delivery_events (
    student_id text NOT NULL,
    event_id text NOT NULL,
    payload jsonb NOT NULL,
    PRIMARY KEY (student_id, event_id)
);
